select ,
from customization_option_tier_prices cotp left join tiers tier on tier.id = cotp.tier_id where (cotp.is_deleted = 0 or cotp.is_deleted is null) and cotp.tier_id = #{tierId,jdbcType=INTEGER} and cotp.customization_option_id in
